-- TESTING ONLY - restores @black's Wall document to the revision-13 backup (taken 2026-09-28, before the Espada visual stress test).
-- It goes through the owner's own save RPC (public.save_my_wall_draft: full Wall validation, owner's-assets check, revision check), acting as the
-- @black owner inside this one transaction. It changes ONLY the Wall document (a new revision); identity data and uploaded assets are untouched.
-- Run:  supabase db query --linked -f docs/testing-backups/restore-black-wall-rev13.sql
do $restore$
declare
  ent uuid; owner_id uuid; current_revision bigint;
  backup jsonb := $bk${"background":{"assetId":"a312ce52-6cff-496f-8c05-9c17b79a9d35","fit":"contain","kind":"image","opacity":1,"posX":50,"posY":0},"canvas":{"height":1778,"width":1000},"schemaVersion":1,"stages":[{"background":{"assetId":"a312ce52-6cff-496f-8c05-9c17b79a9d35","fit":"cover","kind":"image","opacity":1,"posX":50,"posY":50},"elements":[{"height":520,"id":"el_15","payload":{"block":"games","layout":"card"},"type":"gamid","width":800,"x":100,"y":152,"z":0}],"id":"stage_2"},{"elements":[{"height":240,"id":"el_13","payload":{"data":{"id":"gaben","kind":"profile","presentation":"card"},"providerKey":"steam"},"type":"embed","width":800,"x":73,"y":697,"z":0},{"groupId":"group_2","height":260,"id":"el_9","payload":{"data":{"id":"midjourney","kind":"invite","presentation":"card"},"providerKey":"discord"},"type":"embed","width":800,"x":32,"y":1002,"z":1},{"groupId":"group_2","height":450,"id":"el_5","payload":{"data":{"id":"67124108","kind":"video","presentation":"embed"},"providerKey":"vimeo"},"type":"embed","width":800,"x":0,"y":476,"z":2}],"id":"stage_3"},{"background":{"assetId":"8db9f816-ecdb-4646-aef5-9d4a2ac1da0c","fit":"cover","kind":"image","opacity":1,"posX":50,"posY":50},"elements":[{"height":67,"id":"el_7","payload":{"data":{"id":"82-jTNka3uc","kind":"video","presentation":"card"},"providerKey":"youtube"},"type":"embed","width":206,"x":737,"y":82,"z":0},{"height":200,"id":"el_4","payload":{"block":"roles","layout":"card"},"type":"gamid","width":800,"x":73,"y":0,"z":1},{"groupId":"group_1","height":59,"id":"el_6","payload":{"fill":"#62e7ff","radius":48},"rotation":90,"type":"rect","width":146,"x":520,"y":1124,"z":2},{"groupId":"group_1","height":59,"id":"el_8","payload":{"fill":"#62e7ff","radius":48},"rotation":90,"type":"rect","width":146,"x":429,"y":1124,"z":3},{"height":260,"id":"el_3","payload":{"block":"connections","layout":"card","style":{"bgAngle":0,"bgColor":"#c4649c","bgColor2":"#170d0f","bgOpacity":1}},"type":"gamid","width":800,"x":73,"y":894,"z":4},{"height":607,"id":"el_11","payload":{"data":{"id":"deenthegreat/01a0d895-5b30-7ffd-b313-26c164911428","kind":"video","presentation":"card"},"providerKey":"kick"},"type":"embed","width":882,"x":40,"y":1171,"z":5},{"height":96,"id":"el_12","payload":{"data":{"id":"deenthegreat/01a0d895-5b30-7ffd-b313-26c164911428","kind":"video","presentation":"link"},"providerKey":"kick"},"type":"embed","width":738,"x":11,"y":1024,"z":6},{"height":72,"id":"el_1","payload":{"align":"left","color":"#ffffff","direction":"auto","fontFamily":"system-serif","fontSize":56,"fontWeight":400,"glow":{"blur":100,"color":"#62e7ff"},"italic":false,"letterSpacing":0,"lineHeight":1.35,"opacity":1,"shadow":{"blur":8,"color":"#000000","x":10,"y":28},"text":"mazen mohammed ","underline":false,"wrap":true},"type":"text","width":653,"x":144,"y":356,"z":7},{"height":327,"id":"el_2","payload":{"data":{"id":"82-jTNka3uc","kind":"video","presentation":"embed"},"providerKey":"youtube"},"type":"embed","width":582,"x":41,"y":200,"z":8},{"height":620,"id":"el_10","payload":{"data":{"id":"740414742532100096","kind":"post","presentation":"embed"},"providerKey":"x"},"type":"embed","width":560,"x":174,"y":82,"z":9},{"height":715,"id":"el_14","payload":{"data":{"id":"DdmzOBBPcT8","kind":"reel","presentation":"embed"},"providerKey":"instagram"},"type":"embed","width":940,"x":0,"y":0,"z":10}],"id":"stage_1"}]}$bk$::jsonb;
begin
  select e.entity_id into ent from public.entities e where e.gamid_handle = 'black';
  select m.user_id into owner_id from public.entity_memberships m where m.entity_id = ent and m.role = 'OWNER' limit 1;
  select d.revision into current_revision from public.wall_drafts d where d.entity_id = ent;
  perform set_config('request.jwt.claims', json_build_object('sub', owner_id, 'role', 'authenticated')::text, true);
  set local role authenticated;
  perform public.save_my_wall_draft(backup, current_revision);
  reset role;
  raise notice 'restored @black Wall from backup revision 13 (saved over revision %)', current_revision;
end
$restore$;